  var PHRASES = [["our father", "Our Father"], ["hail mary", "Hail Mary"], ["glory be", "Glory Be"], ["holy spirit", "Holy Spirit"], ["sermon on the mount", "Sermon on the Mount"], ["guru nanak", "Guru Nanak"], ["guru granth sahib", "Guru Granth Sahib"], ["golden temple", "Golden Temple"], ["the prophet", "the Prophet"], ["yom kippur", "Yom Kippur"], ["mata tripta", "Mata Tripta"], ["mark's gospel", "Mark's gospel"], ["christmas eve", "Christmas Eve"], ["rosh hashanah", "Rosh Hashanah"]];
  var ABRA = { olive: 1, angelus: 1, pomegranate: 1, datepalm: 1, nectar: 1, wild: 1 };
  var RE = new RegExp("(^|[^A-Za-z'-])(" + NAMES.map(function (n) { return n.toLowerCase().replace(/'/g, "'"); }).join("|") + ")(?![A-Za-z])", "g");
  var MAP = {}; NAMES.forEach(function (n) { MAP[n.toLowerCase()] = n; });
